import { world } from "@minecraft/server";

let isProcessing = false;
const MAX_BLOCKS = 64;

world.afterEvents.playerBreakBlock.subscribe((event) => {
  if (isProcessing) return;

  const { block, brokenBlockPermutation, dimension } = event;
  const targetTypeId = brokenBlockPermutation.type.id;

  if (!targetTypeId || targetTypeId === "minecraft:air") return;

  isProcessing = true;

  try {
    const queue = [];
    const visited = new Set();
    const startLoc = block.location;

    const key = (x, y, z) => `${x},${y},${z}`;
    visited.add(key(startLoc.x, startLoc.y, startLoc.z));

    const directions = [
      { x: 1, y: 0, z: 0 },
      { x: -1, y: 0, z: 0 },
      { x: 0, y: 1, z: 0 },
      { x: 0, y: -1, z: 0 },
      { x: 0, y: 0, z: 1 },
      { x: 0, y: 0, z: -1 }
    ];

    for (const d of directions) {
      queue.push({ x: startLoc.x + d.x, y: startLoc.y + d.y, z: startLoc.z + d.z });
    }

    let brokenCount = 0;

    while (queue.length > 0 && brokenCount < MAX_BLOCKS) {
      const pos = queue.shift();
      if (!pos) break;

      const posKey = key(pos.x, pos.y, pos.z);
      if (visited.has(posKey)) continue;
      visited.add(posKey);

      const targetBlock = dimension.getBlock(pos);
      if (!targetBlock) continue;

      if (targetBlock.type.id === targetTypeId) {
        dimension.runCommand(`setblock ${pos.x} ${pos.y} ${pos.z} air [] destroy`);
        brokenCount++;

        for (const d of directions) {
          const nextPos = { x: pos.x + d.x, y: pos.y + d.y, z: pos.z + d.z };
          const nextKey = key(nextPos.x, nextPos.y, nextPos.z);
          if (!visited.has(nextKey)) {
            queue.push(nextPos);
          }
        }
      }
    }
  } catch (e) {
  } finally {
    isProcessing = false;
  }
});

