import { world, EntityDamageCause } from "@minecraft/server";

world.beforeEvents.entityHurt.subscribe((event) => {
  if (event.hurtEntity.typeId === "minecraft:player" && event.damageSource.cause === EntityDamageCause.fall) {
    event.cancel = true;
  }
});

